#!/bin/bash
# Kit batch 2005+ b (lane/kit-batch-2005b-20261122): install commands for the integrator.
# Run from the repository root with MAP_RECALL_SOURCE_DATA pointing at a source-data checkout holding the lane crops.
# All six won the blind A/B on 2026-11-22: one fresh opus judge saw photo | A | B with sides drawn by a seeded RNG
# (blind.mjs), ?world=live frames from the staged catalogue, and preferred new 6/6. Sheets and key:
# map-recall2-screenshots/kit-batch-2005b/2026-11-22. Each --allow-inferred note (allow-<id>.txt) says what was read
# by hand and why the automatic likeness judge cannot judge that group.
# Dry run: pass --dry to drop --install.
set -euo pipefail
I=--install; [ "${1:-}" = --dry ] && I=

# Rode Kruisstraat 2
